def make_lesson_questions(row):
    lid, order, sub, concept, fill_term, tf_stmt, match_pairs, num_q, chart_q, essay_q = row
    diffs = (
        ["EASY", "EASY", "EASY", "MEDIUM", "MEDIUM", "MEDIUM", "MEDIUM", "MEDIUM", "HARD", "HARD"]
        if order % 2 == 0
        else ["EASY", "EASY", "EASY", "MEDIUM", "MEDIUM", "MEDIUM", "MEDIUM", "HARD", "HARD", "HARD"]
    )
    out = []

    out.append({
        "id": f"{lid}_n01",
        "lessonId": lid,
        "format": "TRUE_FALSE",
        "difficulty": diffs[0],
        "skill": f"Julgar proposições científicas sobre {sub}",
        "concept": concept,
        "statement": tf_stmt,
        "explanation": f"A afirmação é verdadeira: {tf_stmt} Esse é um conceito central de Biologia sobre {sub}.",
        "retryGuidance": f"Revise os conceitos fundamentais de {sub} e identifique a relação estrutura-função descrita.",
        "source": "AUTORAL",
        "answerBool": True,
    })

    out.append({
        "id": f"{lid}_n02",
        "lessonId": lid,
        "format": "FILL_BLANK",
        "difficulty": diffs[1],
        "skill": f"Identificar a terminologia biológica exata em {sub}",
        "concept": concept,
        "statement": f"No estudo de {sub} ({concept}), o termo-chave estudado na aula que nomeia diretamente esse elemento ou processo principal é ___.",
        "explanation": f"O termo correto é '{fill_term}', conceito indispensável para compreender {sub}.",
        "retryGuidance": f"Releia o resumo de termos-chave da aula de {sub} e confira a grafia do conceito principal.",
        "source": "AUTORAL",
        "answers": list({fill_term, fill_term.lower()}),
    })

    for mc_idx, (qnum, d_slot, p_idx) in enumerate([(3, 2, 0), (5, 4, 2), (6, 5, 3)]):
        target_left, target_right = match_pairs[p_idx]
        other_rights = [p[1] for i, p in enumerate(match_pairs) if i != p_idx]
        raw_opts = [
            f"{target_left}: {target_right}",
            f"{target_left}: {other_rights[0]}",
            f"{target_left}: {other_rights[1]}",
            f"{target_left}: {other_rights[2]}",
            f"{target_left}: Processo abiótico inexistente em seres vivos",
        ]
        raw_dist = [
            "",
            f"Atribuiu a '{target_left}' a descrição que pertence a '{[p[0] for i,p in enumerate(match_pairs) if i!=p_idx][0]}'",
            f"Atribuiu a '{target_left}' a descrição que pertence a '{[p[0] for i,p in enumerate(match_pairs) if i!=p_idx][1]}'",
            f"Atribuiu a '{target_left}' a descrição que pertence a '{[p[0] for i,p in enumerate(match_pairs) if i!=p_idx][2]}'",
            f"Desconsiderou o papel biológico real de '{target_left}' em {sub}",
        ]
        shift = (order + mc_idx * 2) % 5
        opts = raw_opts[shift:] + raw_opts[:shift]
        dist = raw_dist[shift:] + raw_dist[:shift]
        ans = (0 - shift) % 5
        out.append({
            "id": f"{lid}_n{qnum:02d}",
            "lessonId": lid,
            "format": "MULTIPLE_CHOICE",
            "difficulty": diffs[d_slot],
            "skill": f"Relacionar estrutura, mecanismo e função em {sub}",
            "concept": f"{target_left} em {sub}",
            "statement": f"Considerando os mecanismos biológicos estudados em {sub}, assinale a alternativa que descreve corretamente '{target_left}':",
            "explanation": f"A alternativa correta associa '{target_left}' a: {target_right}. As demais opções trocam conceitos de outros elementos da aula.",
            "retryGuidance": f"Diferencie '{target_left}' dos demais processos de {sub} verificando onde ocorre e qual é seu resultado fisiológico ou ecológico.",
            "source": "AUTORAL",
            "options": opts,
            "answerIndex": ans,
            "distractorConcepts": dist,
        })

    out.append({
        "id": f"{lid}_n04",
        "lessonId": lid,
        "format": "MATCHING",
        "difficulty": diffs[3],
        "skill": f"Associar conceitos e mecanismos de {sub}",
        "concept": concept,
        "statement": f"Associe cada elemento ou processo de {sub} à sua respectiva definição biológica:",
        "explanation": "O domínio das relações entre estruturas e funções biológicas permite interpretar situações-problema interdisciplinares com precisão.",
        "retryGuidance": f"Revise cada par comparando os termos de {sub} com suas funções específicas.",
        "source": "AUTORAL",
        "pairs": match_pairs,
    })

    n_stmt, n_val, n_ver, n_unit = num_q
    out.append({
        "id": f"{lid}_n07",
        "lessonId": lid,
        "format": "NUMERIC",
        "difficulty": diffs[6],
        "skill": f"Resolver problema quantitativo aplicado a {sub}",
        "concept": concept,
        "statement": n_stmt,
        "explanation": f"Aplicando a proporção quantitativa de {sub} ({n_ver}), obtemos exatamente {n_val} {n_unit}.",
        "retryGuidance": f"Identifique a relação numérica fornecida no enunciado ({n_ver}) e refaça o cálculo com atenção às unidades.",
        "source": "AUTORAL",
        "answerNumber": n_val,
        "tolerance": 0.01,
        "unit": n_unit,
        "verify": n_ver,
    })

    c_title, c_labels, c_sname, c_vals, c_stmt, c_opts, c_dist = chart_q
    shift_c = (order + 1) % 5
    opts_c = c_opts[shift_c:] + c_opts[:shift_c]
    dist_c = c_dist[shift_c:] + c_dist[:shift_c]
    ans_c = (0 - shift_c) % 5
    out.append({
        "id": f"{lid}_n08",
        "lessonId": lid,
        "format": "CHART",
        "difficulty": diffs[7],
        "skill": f"Interpretar dados experimentais sobre {sub}",
        "concept": concept,
        "statement": c_stmt,
        "explanation": f"Pela leitura dos dados ('{c_title}'), a conclusão correta é: {c_opts[0]}.",
        "retryGuidance": "Compare os valores numéricos de cada categoria do gráfico antes de relacioná-los ao conceito biológico.",
        "source": "AUTORAL",
        "options": opts_c,
        "answerIndex": ans_c,
        "distractorConcepts": dist_c,
        "chart": {
            "type": "bar",
            "title": c_title,
            "labels": c_labels,
            "series": [{"name": c_sname, "values": c_vals}],
            "unit": "",
        },
    })

    out.append({
        "id": f"{lid}_n09",
        "lessonId": lid,
        "format": "TRUE_FALSE",
        "difficulty": diffs[8],
        "skill": f"Avaliar criticamente causa e consequência em {sub}",
        "concept": concept,
        "statement": f"Afirmação incorreta para análise crítica sobre {sub}: '{match_pairs[0][0]}' e '{match_pairs[1][0]}' representam exatamente a mesma estrutura molecular e são processos abióticos independentes de informação genética ou energia.",
        "explanation": f"A afirmação é FALSA: '{match_pairs[0][0]}' ({match_pairs[0][1]}) e '{match_pairs[1][0]}' ({match_pairs[1][1]}) possuem papéis biológicos distintos e bem definidos em {sub}.",
        "retryGuidance": f"Compare as definições de '{match_pairs[0][0]}' e '{match_pairs[1][0]}' para notar por que a afirmação é falsa.",
        "source": "AUTORAL",
        "answerBool": False,
    })

    es_stmt, es_model, es_kw = essay_q
    out.append({
        "id": f"{lid}_n10",
        "lessonId": lid,
        "format": "ESSAY",
        "difficulty": diffs[9],
        "skill": f"Elaborar explicação biológica articulada sobre {sub}",
        "concept": concept,
        "statement": es_stmt,
        "explanation": f"Resposta esperada segundo a rubrica: {es_model}",
        "retryGuidance": f"Inclua em sua resposta os conceitos fundamentais de {sub} solicitados no comando da questão.",
        "source": "AUTORAL",
        "modelAnswer": es_model,
        "passScore": 0.6,
        "rubric": [
            {"criterion": f"Identifica o mecanismo biológico central de {sub}", "points": 4, "keywords": [es_kw[0]]},
            {"criterion": "Relaciona corretamente as estruturas ou variáveis fisiológicas/ecológicas", "points": 3, "keywords": [es_kw[1]]},
            {"criterion": "Explica a consequência funcional, clínica ou ambiental", "points": 3, "keywords": [es_kw[2]]},
        ],
    })

    return out


if __name__ == "__main__":
    all_q = []
    for r in BIO_DATA:
        all_q.extend(make_lesson_questions(r))
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w", encoding="utf-8") as f:
        json.dump(all_q, f, ensure_ascii=False, indent=2)
    print(f"Geradas {len(all_q)} questões em {OUT}")
